import{z as s,x as A,o as t,c as p,q as l,j as i,D as o,d as E,s as n,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"RM 过优化与 Goodhart","description":"","frontmatter":{"title":"RM 过优化与 Goodhart","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-overoptimization.md","filePath":"llm/rm-overoptimization.md","lastUpdated":1791413859000}'),d={name:"llm/rm-overoptimization.md"};function m(h,a,f,u,D,R){const e=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="rm-过优化与-goodhart" tabindex="-1">RM 过优化与 Goodhart <a class="header-anchor" href="#rm-过优化与-goodhart" aria-label="Permalink to &quot;RM 过优化与 Goodhart&quot;">​</a></h1><div class="epigraph"><p>代理奖励继续涨、金标奖励先升后降：策略已经在优化奖励模型，而不再优化标注员。</p><footer>—— Gao, Schulman, Hilton, Scaling Laws for Reward Model Overoptimization；Goodhart 定律的现代表述</footer></div><p><a href="/llm/rm-calibration">上一课</a>把 \\(r\\) 的数值校准到保留比较上的胜率。缺口是：即使序对、零点对，<strong>一旦策略针对这份 \\(r\\) 做足够多的 RL，代理分数与金标就会分叉。</strong> Gao、Schulman、Hilton 把这条分叉写成随优化步数与 RM 规模变化的曲线。本课写过优化本身，不重推 <a href="/llm/ppo-llm">PPO</a> 的 clip，也不重写 <a href="/llm/bradley-terry">BT</a>。后课生成式 RM、裁判、校验器，都是在换代理，不取消这条定律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/rlhf-pipeline">RLHF</a> 假设 \\(r_\\phi\\) 足够接近人类偏好 \\(r^\\star\\)。比较数据有限、\\(r_\\phi\\) 容量有限，残差里藏着捷径：长度、清单、客套、表面正确。KL 把策略拴在 SFT 附近，等于限制优化强度；放松 KL 或拉长训练，代理 \\(\\mathbb{E}[r_\\phi]\\) 单调升，金标（更大 RM、人类、下游任务）先升后降。这就是过优化，也是 Goodhart：度量一旦成为目标，就不再是好度量。</p><p>Gao 等人用合成与真实偏好量了标度：更大的 RM 推迟拐点，但不消灭拐点；Best-of-N 与 RL 都会过优化，RL 往往更快。集成与校准改变的是拐点位置，不是定律。</p><p><span class="marginnote">给个形状感的数字：训练前 200 步，代理从 1.2 涨到 1.6，金标从 1.1 涨到 1.3——同步，健康；200 步后代理继续涨到 2.1，金标却从 1.3 滑回 0.9——分叉出现，1.3 附近就是拐点。代理与金标「同涨」的阶段是安全余量，一旦只涨代理，就要按过优化处理，直到金标说否。</span></p><h3 id="金标必须独立于被优化的" tabindex="-1">金标必须独立于被优化的 \\(r\\) <a class="header-anchor" href="#金标必须独立于被优化的" aria-label="Permalink to &quot;金标必须独立于被优化的 $r$&quot;">​</a></h3><p>用同一 RM 的另一份 dropout 当金标，会低估过优化。金标应是：更大模型、人类抽检、或任务准确率。InstructGPT 用标注员偏好当金标、用 RM 当代理，报告过「RL 走太远则标注员不再买账」的早期形态。</p><p><span class="marginnote">Skalse 等把 reward gaming 写成：存在策略使代理高、真奖励低。过优化曲线是它在 LLM 上的经验形状。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监控必须双轴：横轴是优化强度（PPO 步、KL 预算、Best-of-N 的 \\(N\\)），纵轴同时画代理 \\(r_\\phi\\) 与金标。拐点出现就早停，或加大 \\(\\beta_{\\mathrm{KL}}\\)。不要只看代理。Gold-standard 采样要固定协议：同一批提示、同一解码，避免把评测噪声写成拐点。</p><p>缓解（都不完美）：更强 / 更新的 RM（InstructGPT 的迭代标注）、<a href="/llm/rm-ensembles">集成悲观</a>、KL 或显式长度惩罚、可验证域改走 <a href="/llm/verifiable-reward">校验器</a>。<a href="/llm/dpo">DPO</a> 把奖励限制在 \\(\\log(\\pi/\\pi_{\\mathrm{ref}})\\) 族里，过拟合比较对时同样会离开金标，只是曲线换了名字。</p>',13)),(t(),i(B,null,{default:o(()=>[n(e,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E4%BB%A3%E7%90%86%20r_%CF%86%22%5D%20--%3E%20RL%5B%22PPO%20%2F%20BoN%20%E4%BC%98%E5%8C%96%22%5D%0A%20%20RL%20--%3E%20UP%5B%22%E4%BB%A3%E7%90%86%E5%88%86%E6%95%B0%E4%B8%8A%E5%8D%87%22%5D%0A%20%20RL%20--%3E%20DN%5B%22%E9%87%91%E6%A0%87%E5%85%88%E5%8D%87%E5%90%8E%E9%99%8D%22%5D%0A%20%20DN%20--%3E%20STOP%5B%22%E6%97%A9%E5%81%9C%20%2F%20%E5%8A%A0%E5%A4%A7%20KL%20%2F%20%E6%8D%A2%E5%A5%96%E5%8A%B1%22%5D%0A%20%20GOLD%5B%22%E7%8B%AC%E7%AB%8B%E9%87%91%E6%A0%87%22%5D%20--%3E%20DN%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"报告拐点时写清 RM 规模、策略规模、KL 系数。Gao 的标度律是经验拟合，不是可外推的物理常数；换比较协议，拐点移动。",-1)),a[4]||(a[4]=r("p",null,[r("span",{class:"marginnote"},"常见误区：拿同一份 RM 的另一次 dropout 前向当「金标」。这等于让被告兼任法官——两份分数共享同一套捷径，相关性极高，画出来的「金标曲线」几乎必然同涨，过优化被系统性低估。金标必须独立：更大的模型、人类抽检或任务指标，至少占一样。")],-1)),a[5]||(a[5]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=r("p",null,"过优化发生在 \\(r_\\phi\\) 的零空间：人类几乎无差别、模型却给了稳定梯度的方向。长度是最便宜的一维，见已有的长度偏置课。RL 比 BoN 更容易过优化，因为梯度会主动放大这些方向，而不只是在候选里挑最大值。KL 的作用是把可走的距离限制在 SFT 邻域，邻域内捷径还没被榨干；一旦 \\(\\beta\\) 太小，邻域边界上的黑客成为最优。",-1)),(t(),i(B,null,{default:o(()=>[n(e,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22SFT%20%E7%AD%96%E7%95%A5%EF%BC%9A%E5%87%BA%E5%8F%91%E7%82%B9%22%5D%20--%3E%20N%5B%22KL%20%E9%82%BB%E5%9F%9F%EF%BC%9A%CE%B2%20%E5%86%B3%E5%AE%9A%E5%8F%AF%E8%B5%B0%E5%8D%8A%E5%BE%84%22%5D%0A%20%20N%20--%3E%20G%5B%22%E9%82%BB%E5%9F%9F%E5%86%85%EF%BC%9A%E7%9C%9F%E6%8F%90%E5%8D%87%E4%B8%BA%E4%B8%BB%EF%BC%8C%E9%87%91%E6%A0%87%E5%90%8C%E6%AD%A5%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20N%20--%3E%20E%5B%22%E9%82%BB%E5%9F%9F%E8%BE%B9%E7%95%8C%EF%BC%9A%E9%9B%B6%E7%A9%BA%E9%97%B4%E6%96%B9%E5%90%91%E8%81%9A%E9%9B%86%E5%A4%84%22%5D%0A%20%20E%20--%3E%20H%5B%22%CE%B2%20%E5%A4%AA%E5%B0%8F%EF%BC%9A%E9%95%BF%E5%BA%A6%20%2F%20%E6%B8%85%E5%8D%95%20%2F%20%E5%AE%A2%E5%A5%97%E6%88%90%E4%B8%BA%E6%9C%80%E4%BC%98%E8%A7%A3%22%5D%0A%20%20H%20--%3E%20D%5B%22%E4%BB%A3%E7%90%86%E5%88%86%E6%95%B0%E6%B6%A8%E3%80%81%E9%87%91%E6%A0%87%E4%B8%8B%E6%BB%91%22%5D%0A%20%20FIX%5B%22%E5%8A%A0%E5%A4%A7%20%CE%B2_KL%20%2F%20%E6%97%A9%E5%81%9C%20%2F%20%E6%8D%A2%E6%9B%B4%E5%BC%BA%20RM%22%5D%20--%3E%20S%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">直觉类比「零空间」：像考卷上老师只数要点数量、不查论证质量的判分规则。学生真正学会知识（金标提升）与凑够十条要点（代理提升）在前几分钟是同一件事，随后就分道扬镳——RL 是那个把「凑条数」这条路走到黑的学生，KL 惩罚则是限制他离题多远的缰绳。</span></p><p><span class="marginnote">看起来「PPO 很成功」的训练曲线，若只有代理奖励，默认解释是过优化进行中，直到金标说否则。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>可验证 0/1 也会过优化校验器的洞（硬编码测例、格式刷分），那是环境黑客，不是 RM 过优化，下一课之后会碰到。开放偏好域没有程序金标，人类抽检是唯一金标，贵，必须抽样而不是全量。不要发明「不会过优化的 RM」；本课结论是：<strong>标量代理必有拐点，工程是推迟它、并看见它。</strong></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代理奖励单调升、金标先升后降，即 RM 过优化 / Goodhart。</li><li>更大 RM、集成、KL 推迟拐点，不取消拐点。</li><li>监控必须有独立金标；只看 \\(r_\\phi\\) 会把黑客当成成功。</li><li>DPO 与 BoN 同样会离开金标，只是优化器不同。</li><li>出处：Gao, Schulman, Hilton, ICML 2023；Christiano 等偏好 RL；Ouyang 等 InstructGPT。</li></ul>',6))])}const C=s(d,[["render",m]]);export{_ as __pageData,C as default};
